const cohabSettingsPanelBase=cohabSettingsPanel;
/* COHAB_SETTINGS_SCROLL_V1（2026-11-04）：设置展开后比屏幕高，这一层不能滑，最下面的「模型与路线诊断」点不到。
   现在展开时这一块自己能上下滑（CSS 在三个壳子里）；页面刷新（比如他回话）时保持展开、保持滑到的位置，不弹回顶部。 */
let _cohabSetOpen=false,_cohabSetScroll=0;
cohabSettingsPanel=function(id,o){let panel=cohabSettingsPanelBase(id,o).replace(/<div class="cohab-debug-actions">.*?<\/div>/,'');panel=panel.replace('<details class="cohab-settings"','<details class="cohab-settings"'+(_cohabSetOpen?' open':'')+' ontoggle="_cohabSetOpen=this.open;if(!this.open){_cohabSetScroll=0;const w=this.parentElement;if(w)w.scrollTop=0;}"');if(_cohabSetOpen&&_cohabSetScroll){const keep=_cohabSetScroll;Promise.resolve().then(()=>{const w=document.querySelector('.cohab-settings-wrap');if(w&&_cohabSetOpen)w.scrollTop=keep;});}const manualReply=cohabTogetherScene(o)&&!_offSel&&manualReplySceneOn('offline');const reply=manualReply?`<button type="button" class="cohab-debug-reply" ${_off&&_off.busy?'disabled':''} onclick="offReply()">${_off&&_off.busy?'回应中…':'让TA回'}</button>`:'';return `<div class="cohab-settings-wrap" onscroll="_cohabSetScroll=this.scrollTop">${panel}${reply}</div>`;};
