function cohabSettingsPanel(id,o){const x=cohabSettings(o),c=getC(id),sc=c&&c.sched,manualReply=cohabTogetherScene(o)&&!_offSel&&manualReplySceneOn('offline'),opt=(value,current,label)=>`<option value="${value}" ${current===value?'selected':''}>${label}</option>`,apiOpts=(current,reply)=>`${reply?opt('reply',current,'跟随对话路线'):''}${opt('follow',current,'跟随微信当前路线')}${CHAT_ROUTE_NAMES.map((name,i)=>opt(String(i),current,name)).join('')}`;return `<details class="cohab-settings"><summary><span><b>共同生活设置</b><small id="cohab-settings-brief">${esc(cohabSettingsBrief(o))}</small></span><i>⌄</i></summary>${manualReply?`<div class="cohab-debug-actions"><button type="button" class="cohab-debug-reply" ${_off&&_off.busy?'disabled':''} onclick="offReply()">${_off&&_off.busy?'回应中…':'让TA回'}</button></div>`:''}<div class="cohab-settings-grid"><label><span>最近上下文轮数<small>你说一次、他回一次算一轮</small></span><input type="number" min="10" max="80" step="1" value="${x.contextLimit}" onchange="cohabSettingSet('${id}','contextLimit',this.value,this)"></label><label><span>自动总结<small>0 代表关闭</small></span><input type="number" min="0" max="40" step="1" value="${x.summaryRounds}" onchange="cohabSettingSet('${id}','summaryRounds',this.value,this);this.closest('label').nextElementSibling.innerHTML=summaryProgressView(cohabSummaryCompletedRounds(cohabSummaryRows(cohabData('${id}'))),cohabSummaryRoundLimit(cohabData('${id}')))"><em>轮</em></label><div style="grid-column:1/-1">${summaryProgressView(cohabSummaryCompletedRounds(cohabSummaryRows(o)),x.summaryRounds)}</div><label><span>记忆上限<small>共存多少条，0 表示不限</small></span><input type="number" min="0" max="2000" step="10" value="${x.memoryCap}" onchange="cohabSettingSet('${id}','memoryCap',this.value,this)"></label><label><span>旧总结引用<small>按话题读取这里的记忆</small></span><input type="number" min="1" max="20" step="1" value="${x.summaryMemoryLimit}" onchange="cohabSettingSet('${id}','summaryMemoryLimit',this.value,this)"><em>条</em></label><label><span>总结方式<small>自动与立即总结共用</small></span><select onchange="cohabSettingSet('${id}','summaryMode',this.value,this)">${opt('split',x.summaryMode,'分段重点')}${opt('single',x.summaryMode,'一整段')}</select></label><label><span>对话模型<small>主模型或副模型</small></span><select onchange="cohabSettingSet('${id}','replyModel',this.value,this)">${opt('role',x.replyModel,'跟随微信角色')}${opt('main',x.replyModel,'主模型')}${opt('aux',x.replyModel,'副模型')}</select></label><label><span>对话 API 路线<small>接口地址、Key 与模型组</small></span><select onchange="cohabSettingSet('${id}','replyApiRoute',this.value,this)">${apiOpts(x.replyApiRoute,false)}</select></label><label><span>总结模型<small>只影响共同生活总结</small></span><select onchange="cohabSettingSet('${id}','summaryModel',this.value,this)">${opt('reply',x.summaryModel,'跟随对话模型')}${opt('main',x.summaryModel,'主模型')}${opt('aux',x.summaryModel,'副模型')}</select></label><label><span>总结 API 路线<small>只影响共同生活总结</small></span><select onchange="cohabSettingSet('${id}','summaryApiRoute',this.value,this)">${apiOpts(x.summaryApiRoute,true)}</select></label><label><span>台词播放<small>点一下屏幕出下一句</small></span><select onchange="cohabSettingSet('${id}','tapAdvance',this.value,this)">${opt('0',x.tapAdvance?'1':'0','自动一句句出')}${opt('1',x.tapAdvance?'1':'0','点一下出一句')}</select></label><label><span>他自己查你手机<small>每日必查不受影响</small></span><select onchange="cohabSettingSet('${id}','autoInspect',this.value,this)">${opt('1',x.autoInspect?'1':'0','开')}${opt('0',x.autoInspect?'1':'0','关')}</select></label><label><span>查手机冷却时间<small>查过或问过后，至少等这么久</small></span><input type="number" min="5" max="180" step="5" value="${x.autoInspectGap}" onchange="cohabSettingSet('${id}','autoInspectGap',this.value,this)"><em>分钟</em></label><label><span>每天最多问<small>0 表示不限</small></span><input type="number" min="0" max="100" step="1" value="${x.autoInspectMax}" onchange="cohabSettingSet('${id}','autoInspectMax',this.value,this)"><em>次</em></label><div class="hint" style="grid-column:1/-1;padding:0 2px;line-height:1.65">“对话模型”与“对话 API 路线”都选择跟随时，会完整继承微信里该角色的主/副模型选择和微信当前路线；固定路线只影响共同生活，不会切换微信。</div><button type="button" class="cohab-memory-open cohab-schedule-open" onclick="schedSet('${id}')"><span>作息时间表</span><small>${esc(roleScheduleBrief(c))} ›</small></button><button type="button" class="cohab-memory-open cohab-history-delete" onclick="offDelHistory('${id}')"><span>删除聊天记录</span><small>按日期 / 一天前 / 三天前 / 全部清空 ›</small></button><button type="button" class="cohab-memory-open" onclick="cohabMemoryOpen('${id}')"><span>查看共同生活记忆</span><small>${(o.summaries||[]).length} 条 ›</small></button><button type="button" class="cohab-memory-open" onclick="roleInterceptDiagnosticOpen('${id}','cohab')"><span>查看上一轮拦截内容</span><small>仅本机诊断 ›</small></button><button type="button" class="cohab-memory-open cohab-summary-now" onclick="cohabSummarizeNow('${id}')"><span>立即总结</span><small>${x.summaryMode==='split'?'分段':'整段'} ›</small></button></div></details>`;}
