function phCleanSmsText(t){return cleanRolePunct(String(t||'').replace(/^[\[【]\s*(?:心情|心情值|通话语气|语气|情绪|系统|隐藏)[|｜:：][^\]】]*[\]】]\s*/g,'').replace(/[\[【]\s*(?:心情|心情值|通话语气|语气|情绪|系统|隐藏)[|｜:：][^\]】]*[\]】]/g,'').replace(/声音不对|听起来不对|声线不对|语音不对/g,'文字有点像').replace(/\n+/g,' ').trim()).trim();}
function phSpoofSmsPolish(r,style,seed,kind){r=phCleanSmsText(r).slice(0,180);if(/睡了吗|睡没睡|睡了没|睡着了吗|还醒着吗|天气|气温|温度|下雨|苏州|路过|顺便看看|待得习惯|最近怎么样|没事[，, ]*就是|方便说话|方便聊|猜猜我是谁|认错人|认错了|找错人|弄错人|发错人|看错人|误会了|不好意思.{0,8}(发错|找错|认错)/.test(r))r='';r=phSpoofNoWrongSms(r);if(!r||/你先回答刚才那句。/.test(r))return phSpoofSmsFallback(style,seed,kind);return r;}
function phIdentityAskText(t){return /(你是谁|你谁|哪位|谁啊|谁呀|who are you|who is this|who'?s this|may i know who|请问你是)/i.test(String(t||''));}
