function phSpoofCallAdvance(role,pf){const key=pf&&pf.spoofStyle,lang=(getVoice(role).lang||'zh');if(lang==='粤')return key==='yandere_call'?'唔好再問我係邊個，問下點解我成日打畀你。\n（别再问我是谁，问我为什么一直打给你。）':'唔好再問我係邊個，答咗我先。\n（别再问我是谁，先回答我。）';if(lang==='英')return key==='yandere_call'?'Stop asking who I am. Ask why I keep calling you.\n（别再问我是谁，问我为什么一直打给你。）':'Don’t ask who I am again. Answer me first.\n（别再问我是谁，先回答我。）';if(lang==='日')return '誰かはまだ聞かないで。先に答えて。\n（先别问我是谁，先回答我。）';if(lang==='韩')return '누군지는 아직 묻지 마. 먼저 대답해.\n（先别问我是谁，先回答我。）';if(key==='yandere_call'||key==='ghost_call')return '别一直问我是谁。你应该问，我为什么偏偏打给你。';if(key==='jealous_call')return '别管我是谁，先说你为什么会接陌生电话。';return '别再问我是谁了，先回答我一句。';}
