function phAliasPushback(arr,seed){const pool=['别绕了，说重点。','你再这样发，我就当骚扰处理。','如果只是来闹的，这个号码我会拉黑。','你已经问够了。换一句有用的。','再试探下去，我不会继续回。'];return pool[Math.abs(phHash(seed+':alias-push'))%pool.length];}
function phAliasQuestionFallback(seed){const pool=['你想做什么？','找我有什么事。','别绕圈，直接说。','你到底想问什么。','先说你的来意。'];return pool[Math.abs(phHash(seed+':alias-q'))%pool.length];}
