function phCallLangPrompt(c){const lang=normVoiceLang(getVoice(c).lang||'zh'),name=voiceLangName(lang);if(!name)return '\n# 电话语言\n使用中文口语短句。';const eg=lang==='粤'?'邊位呀？\n（你是谁？）':lang==='韩'?'누구세요?\n（你是谁？）':lang==='日'?'どなたですか？\n（你是谁？）':'Who is this?\n（你是谁？）';return '\n# 电话语言（必须和微信电话一致）\n- 角色当前电话语言是'+name+'，你全程先说'+name+'原文。\n- 每一句都严格按两行：第一行'+name+'原文，下一行用（）写普通话中文翻译。一句原文配一句翻译，不要混在同一行。\n- '+voiceOriginalRule(lang)+'\n- 英语原文里叫宝贝写 baby/babe/darling，中文翻译行必须写宝贝/亲爱的，不能照抄 baby；英语自称使用 I/me 等自然说法。\n- 只输出电话里说的话和必要隐藏指令，不要解释格式。\n例：\n'+eg;}
