function phCallAdmits(text){const s=String(text||'').trim();if(/^(?:嗯[，,、\s]*)?(?:不是(?:我|本人)?|不对|猜错|不认识|not me|is not me|isn't me|wrong guess)/i.test(s))return false;return /(是我|我是|我啊|认出来|看出来|猜到|别装|it'?s me|this is me|you got me|わたし|私だ|나야|저야)/i.test(s);}
function phAdmitFallback(c,kind){const gv=(typeof getVoice==='function'?getVoice(c):{}),lang=(gv.lang||'zh'),seed=(c&&c.id||c&&c.name||'role')+':'+(kind||'sms')+':'+Math.floor(Date.now()/60000),hash=s=>{if(typeof phHash==='function')return phHash(s);let h=0;for(let i=0;i<String(s).length;i++)h=(h*31+String(s).charCodeAt(i))|0;return h;},pick=a=>a[Math.abs(hash(seed))%a.length];if(lang==='粤')return pick(['係我呀。\n（是我。）','畀你估中咗。\n（被你猜到了。）','好啦，畀你捉到喇。\n（行，被你抓到了。）','我就知你會發現。\n（我就知道你会发现。）']);if(lang==='英')return pick(['It is me.\n（是我。）','You got me.\n（被你猜到了。）','Fine. You found me.\n（行，被你抓到了。）','I knew you would notice.\n（我就知道你会发现。）']);if(lang==='日')return pick(['私だよ。\n（是我。）','ばれちゃったね。\n（被你发现了。）','見つかったか。\n（被你抓到了。）']);if(lang==='韩')return pick(['나야.\n（是我。）','들켰네.\n（被你发现了。）','알아봤구나.\n（你认出来了。）']);return pick(['我。','被你猜到了。','行，被你抓到了。','你认出来了。','我就知道你会发现。']);}
function phStripFalseAdmit(r){return String(r||'').replace(/^(?:嗯[，,、\s]*)?(?:不是(?:我|本人)?|不对|猜错了?|猜错|没有|不认识)[。！？!?,，、\s]*/i,'').replace(/([。！？!?,，、\s]|^)(?:不是(?:我|本人)?|不对|猜错了?|猜错|没有|不认识)[。！？!?,，、\s]*/i,'$1').trim();}
